namespace StarlightSyndicateDemo;
public static class RigTests
{
 static int checks;static void Check(bool ok,string name){if(!ok)throw new Exception("RIG FAIL: "+name);checks++;Console.WriteLine("RIG PASS: "+name);}
 static void LiveChecks()
 {
  RigDefinition D(string family,int size=1)=>RigCatalog.All.First(d=>d.Family==family&&d.Size==size);
  DemoWorld W(string hull="frigate"){var w=new DemoWorld();w.NewGame(0);w.RigTrial(hull);return w;}
  var warp=W();float cost=warp.WarpEnergyCost();Check(warp.FitRig(D("Warp Core Optimizer").Id,true,0)&&warp.WarpEnergyCost()<cost,"Warp economy changes charged transit energy");warp.Player.Cap=warp.Player.MaxCap;float start=warp.Player.Cap,charge=warp.WarpEnergyCost();Check(warp.PayWarpEnergy()&&Math.Abs(start-warp.Player.Cap-charge)<.001,"Actual warp capacitor payment");warp.Player.Cap=0;Check(!warp.PayWarpEnergy(),"Empty capacitor blocks warp");
  var fitting=W();var current=D("Ancillary Current Router");Check(fitting.FitRig(current.Id,true,0),"Reactor rig installation");fitting.Player.SetStat("powerOutput",22);Check(!fitting.RemoveRig(0,true)&&fitting.Player.Rigs[0]==current.Id,"Supporting rig removal cannot orphan an over-budget fitting");
  var anchor=W();Check(anchor.FitRig(D("Higgs Anchor").Id,true,0)&&!anchor.FitRig(D("Higgs Anchor").Id,true,1),"Anchor unique fitting limit");anchor.Player.SetStat("warpBubbleImmune",1);Check(anchor.Player.Stat("warpBubbleImmune")==0,"Anchor removes interdiction immunity");
  var command=W("battlecruiser");int limit=command.BurstLimit;Check(command.FitRig(D("Command Processor",2).Id,true,0)&&command.BurstLimit==limit+1,"Command rig unlocks an actual additional burst");
  var shield=W("cruiser");var boost=DefenseCatalog.All.First(d=>d.Kind=="ShieldBoost"&&d.Size==1);shield.Player.Defense[1]=DefenseState.Create(boost.Id);shield.FitRig(D("Core Defense Operational Solidifier",2).Id,true,0);shield.Undock();shield.Player.Cap=shield.Player.MaxCap;float cap=shield.Player.Cap;Check(shield.ToggleDefense(1),"Shield cadence rig real booster activation");Check(Math.Abs(cap-shield.Player.Cap-boost.Capacitor)<.01,"Faster repair still pays full energy per cycle");Check(shield.Player.Defense[1].CycleLeft<boost.Cycle,"Shield cadence changes real cycle duration");
  var data=W();var analyzer=UtilityCatalog.All.First(d=>d.Kind=="Data");data.FitUtility(analyzer.Id,true,8);data.FitRig(D("Memetic Algorithm Bank").Id,true,0);data.EnterUtilityRange();data.LockedId="ut_Data";data.Player.Cap=data.Player.MaxCap;Check(data.ToggleUtility(8)&&data.UtilityHackState?.MaxCoherence==analyzer.VirusCoherence+10,"Data rig modifies actual hacking board coherence");
  var drones=W();drones.LoadDrone("dr_2203",true,1);var unit=drones.Player.Drones.First(x=>x.Owner=="player"&&x.Location=="Bay");float hull=unit.Hull;Check(drones.FitRig(D("Drone Durability Enhancer").Id,true,0)&&unit.Hull>hull,"Durability fitting updates existing bay drone health");Check(drones.UnloadDrone(unit.Id)&&Math.Abs(unit.Hull-hull)<.001,"Unload normalizes rig enhancement before stock transfer");Check(drones.LoadDrone("dr_2203",true,1)&&drones.Player.Drones.First(x=>x.Owner=="player"&&x.Location=="Bay").Hull>hull,"Reload reapplies rig health without accumulation");
  var training=W();training.WeaponTestMode=false;training.Credits=10000;float credits=training.Credits;Check(training.TrainRiggingSkill("Armor")&&training.Credits==credits-1000&&training.Player.RiggingSkills["Armor"]==1,"Campaign rigging training pays credits");
 }
 public static void Run()
 {
  Check(RigCatalog.All.Length==326,"326 published ship rigs");Check(RigCatalog.All.Select(d=>d.Family).Distinct().Count()==83,"83 unique functional families");
  foreach(var d in RigCatalog.All)
  {
   var w=new DemoWorld();w.NewGame(0);w.RigTrial(new[]{"","frigate","cruiser","battleship","carrier"}[d.Size]);var p=w.Player;Check(ItemCatalog.All.Any(i=>i.Id==d.Id),d.Name+" inventory database");Check(w.Offers(d.Id,w.SystemId,false).Any(),d.Name+" market");var before=p.Attributes.Keys.ToDictionary(k=>k,k=>p.Stat(k));float count=w.ItemCount(d.Id,true);Check(w.FitRig(d.Id,true,0),d.Name+" installation");Check(w.ItemCount(d.Id,true)==count-1,d.Name+" stock consumed");Check(p.RigCalibration==d.Calibration,d.Name+" calibration charged");Check(p.Stat("upgradeSlotsLeft")==2,d.Name+" occupied socket");Check(!w.FitRig(d.Id,true,0),d.Name+" occupied socket rejects replacement");foreach(var b in d.Bonuses.Where(b=>before.ContainsKey(b.Key)))Check(Math.Abs(p.Stat(b.Key)-before[b.Key])>Math.Max(1e-12,Math.Abs(before[b.Key])*.00001),d.Name+" live ship attribute "+b.Key);
   foreach(var m in d.Modifiers.Where(m=>m.Attribute is "cpu" or "power")) {string? id=m.Targets.FirstOrDefault();if(id!=null)Check(Math.Abs(p.RigModuleFactor(id,m.Attribute)-1)>.00001,d.Name+" affected module fitting cost");}
   foreach(string family in new[]{"Laser","Hybrid","Projectile","Missile"})foreach(string key in new[]{"damage","cycle","tracking","optimal","falloff","cap"})if(d.Bonuses.ContainsKey(family+key)){var gun=WeaponCatalog.All.First(x=>Ship.RigWeaponFamily(x)==family);float factor=key is "tracking" or "optimal" or "falloff"?p.WeaponProjection(gun,key):key=="cap"?p.RigWeapon(gun,key):p.WeaponEnhancement(gun,key);Check(Math.Abs(factor-1)>.00001,d.Name+" live weapon "+key);}
   if(d.Group=="Drones"){var drone=DroneCatalog.All.First(x=>d.Family=="Sentry Damage Augmentor"?x.Kind=="Sentry":d.Family=="Drone Repair Augmentor"?x.RepairDrone:d.Family=="Drone Mining Augmentor"?x.Kind=="Mine":d.Family=="Stasis Drone Augmentor"?x.Kind=="Web":x.Kind=="Combat");var live=drone.Enhanced(p);Check(d.Family switch{"Drone Control Range Augmentor"=>p.Stat("droneControlDistance")>before["droneControlDistance"],"Drone Durability Enhancer"=>live.Shield>drone.Shield&&live.Armor>drone.Armor&&live.Hull>drone.Hull,"Drone Repair Augmentor"=>live.Repair>drone.Repair,"Drone Mining Augmentor"=>live.Yield>drone.Yield,"Drone Speed Augmentor"=>live.Speed>drone.Speed,"Drone Scope Chip"=>live.Optimal>drone.Optimal,"Sentry Damage Augmentor"=>live.Packet.Total>drone.Packet.Total,"Stasis Drone Augmentor"=>live.Strength>drone.Strength,_=>false},d.Name+" live drone behavior");}

   foreach(var b in d.Drawbacks){p.RiggingSkills[d.Group]=0;float raw=p.RigDrawbackFactor(b.Key);p.RiggingSkills[d.Group]=5;float trained=p.RigDrawbackFactor(b.Key);Check(d.Unique||d.Family=="Processor Overclocking Unit"?raw==trained:Math.Abs(trained-1)<Math.Abs(raw-1),d.Name+" drawback training "+b.Key);}
   Check(!w.RemoveRig(0)&&w.PendingRigRemoval==0,d.Name+" confirmation required");p.RiggingSkills.Clear();Check(w.RemoveRig(0,true),d.Name+" destruction");Check(w.ItemCount(d.Id,true)==count-1&&p.Rigs[0]=="",d.Name+" no recovered rig");p.SetStat("rigSize",d.Size==1?2:1);Check(!w.FitRig(d.Id,true,0),d.Name+" incorrect hull size rejected");p.SetStat("rigSize",d.Size);p.SetStat("upgradeCapacity",d.Calibration-1);Check(!w.FitRig(d.Id,true,0),d.Name+" insufficient calibration rejected");
  }
  var save=new DemoWorld();save.NewGame(0);save.RigTrial();var rig=RigCatalog.All.First(d=>d.Size==1&&d.Family=="Capacitor Control Circuit");double baseline=save.Player.Stat("rechargeRate");Check(save.FitRig(rig.Id,true,0)&&save.Player.Stat("rechargeRate")<baseline,"live capacitor recharge");save.Player.RiggingSkills["Core"]=4;save.Save();Check(true,"save rigged hull");var loaded=new DemoWorld();Check(loaded.Load()&&loaded.Player.Rigs[0]==rig.Id&&loaded.Player.RiggingSkills["Core"]==4,"persistent rig and skill");loaded.Undock();Check(!loaded.RemoveRig(0,true)&&!loaded.FitRig(rig.Id,false,1),"space installation and removal prohibited");
  LiveChecks();Console.WriteLine($"{checks} rig checks passed.");
 }
}
